                _this8.saveLoading = false;
              });
            }).catch(function () {
              _this8.saveLoading = false;
            });
          } else {
            _this8.$confirm(markedWords, '提示', {
              confirmButtonText: '确定',
              cancelButtonText: '取消',
              type: 'warning'
            }).then(function () {
              updateInfoInspectionOrder(_this8.childDialogForm).then(function (res) {
                _this8.saveLoading = false;
                if (res.code === 200) {
                  _this8.$message({
                    type: 'success',
                    message: '编辑成功！'
                  });
                  _this8.returnEvent();
                } else {
                  _this8.$message({
                    type: 'error',
                    message: res.msg
                  });
                }
              }).catch(function () {
                _this8.saveLoading = false;
              });
            }).catch(function () {
              _this8.saveLoading = false;
            });
          }
        }
      });
    },
    // 字符串转时间判断
    changeTime: function changeTime(str) {
      if (new Date(str).getTime() < new Date().getTime()) {
        this.$message({
          type: 'error',
          message: '结束时间不能早于当前时间！'
        });
        return false;
      }
      return new Date(str).getTime() < new Date().getTime();
    },
    returnEvent: function returnEvent() {
      if (this.operatorType === 'add') {
        this.$router.push('/xcnanr/ideal/inspectionOrder/index');
      } else {
        this.$router.push('/xcnanr/ideal/inspectionOrder/index');
      }
    },
    formatTime: function formatTime(date) {
      if (date) {
        return "".concat(date.getHours().toString().padStart(2, '0'), ":").concat(date.getMinutes().toString().padStart(2, '0'), ":").concat(date.getSeconds().toString().padStart(2, '0'));
      }
      return '';
    }
  }
};
